1	import { z } from "zod";
2	import {
3	  emailSchema,
4	  memberIdSchema,
5	  orgIdSchema,
6	  pageRequestSchema,
7	  userIdSchema,
8	} from "./common";
9	import { invitableRoleSchema, memberStatusSchema, roleSchema } from "./role";
10	
11	export const inviteMemberSchema = z.object({
12	  orgId: orgIdSchema,
13	  email: emailSchema,
14	  role: invitableRoleSchema.default("member"),
15	  message: z.string().max(500).optional(),
16	});
17	
18	/** Bulk invite from the members settings page; the seat check runs once. */
19	export const inviteMembersSchema = z.object({
20	  orgId: orgIdSchema,
21	  invites: z
22	    .array(
23	      z.object({
24	        email: emailSchema,
25	        role: invitableRoleSchema.default("member"),
26	      }),
27	    )
28	    .min(1)
29	    .max(50),
30	});
31	
32	export const acceptInvitationSchema = z.object({
33	  token: z.string().min(16),
34	});
35	
36	export const revokeInvitationSchema = z.object({
37	  orgId: orgIdSchema,
38	  invitationId: z.string().min(1),
39	});
40	
41	export const updateMemberRoleSchema = z.object({
42	  orgId: orgIdSchema,
43	  memberId: memberIdSchema,
44	  role: roleSchema,
